struct Kiss32Random {
  uint32_t x;
  uint32_t y;
  uint32_t z;
  uint32_t c;

  static const uint32_t default_seed = 123456789;
#if __cplusplus < 201103L
  typedef uint32_t seed_type;
#endif

  Kiss32Random(uint32_t seed = default_seed) {
    x = seed;
    y = 362436000;
    z = 521288629;
    c = 7654321;
  }

  uint32_t kiss() { ... }
  inline int flip() { return kiss() & 1; }
  inline size_t index(size_t n) { return kiss() % n; }
  inline void set_seed(uint32_t seed) { x = seed; }
};

